const response = $json;
if (!response.access_token || typeof response.access_token !== 'string') {
  const safe = { ...response };
  delete safe.access_token;
  throw new Error(`Failed to get Shopify access token: ${JSON.stringify(safe)}`);
}
return [{ json: { access_token: response.access_token, expires_in: response.expires_in ?? null } }];

const response = $json;
if (Array.isArray(response.errors) && response.errors.length) {
  throw new Error(`Failed to get Shopify primary location: ${response.errors.map(e => e.message).join('; ')}`);
}
const location = response.data?.location;
if (!location?.id) {
  throw new Error('Shopify did not return a primary location. Make sure the app has read_locations + inventory access and the store has an active location.');
}
if (location.isActive === false) {
  throw new Error(`Shopify primary location "${location.name ?? location.id}" is inactive.`);
}
return [{ json: { locationId: location.id, locationName: location.name ?? '', isActive: location.isActive ?? true } }];

const cfg = $('CONFIG - EDIT ME').first().json;
const rows = $input.all();

const stockBuffer = Number(cfg.stockBuffer ?? 0);
const priceMultiplier = Number(cfg.priceMultiplier ?? 1);
if (!Number.isFinite(stockBuffer) || stockBuffer < 0) throw new Error('CONFIG stockBuffer must be a non-negative number');
if (!Number.isFinite(priceMultiplier) || priceMultiplier <= 0) throw new Error('CONFIG priceMultiplier must be greater than 0');

const normalizedSku = (value) => String(value ?? '').trim();
const hasValue = (value) => value !== undefined && value !== null && String(value).trim() !== '';
const escapeShopifySearchValue = (value) => {
  let escaped = '';
  for (const ch of value) {
    if (ch === '\\' || ch === ':' || ch === '(' || ch === ')' || ch === '"') escaped += '\\';
    escaped += ch;
  }
  return `"${escaped}"`;
};

const skuCounts = new Map();
for (const item of rows) {
  const sku = normalizedSku(item.json[cfg.skuColumn]);
  if (sku) skuCounts.set(sku, (skuCounts.get(sku) ?? 0) + 1);
}

return rows.map((item, index) => {
  const raw = item.json;
  const sku = normalizedSku(raw[cfg.skuColumn]);
  const rawStock = raw[cfg.stockColumn];
  const rawPrice = raw[cfg.priceColumn];
  const stock = hasValue(rawStock) ? Number(rawStock) : Number.NaN;
  const price = hasValue(rawPrice) ? Number(rawPrice) : Number.NaN;
  const problems = [];

  if (!sku) problems.push(`Missing SKU in column "${cfg.skuColumn}"`);
  if (sku && (skuCounts.get(sku) ?? 0) > 1) problems.push(`Duplicate supplier SKU: ${sku}`);
  if (cfg.updateStock && (!Number.isFinite(stock) || !Number.isInteger(stock) || stock < 0)) {
    problems.push(`Invalid stock in column "${cfg.stockColumn}" (expected a non-negative integer)`);
  }
  if (cfg.updatePrice && (!Number.isFinite(price) || price <= 0)) {
    problems.push(`Invalid price in column "${cfg.priceColumn}" (expected a number greater than 0)`);
  }

  return {
    json: {
      rowNumber: index + 2,
      sku,
      shopifySkuQuery: sku ? `sku:${escapeShopifySearchValue(sku)}` : '',
      supplierStock: Number.isFinite(stock) ? stock : null,
      supplierPrice: Number.isFinite(price) ? price : null,
      valid: problems.length === 0,
      status: problems.length === 0 ? 'valid' : 'invalid',
      message: problems.join('; ')
    },
    pairedItem: { item: index }
  };
});

