const cfg = $('CONFIG - EDIT ME').first().json;
const row = $('Normalize & Validate').item.json;
const response = $json;

if (Array.isArray(response.errors) && response.errors.length) {
  return [{ json: { ...row, status: 'error', message: `Shopify query error: ${response.errors.map(e => e.message).join('; ')}`, needsSync: false } }];
}

const searchMatches = response.data?.productVariants?.nodes ?? [];
const matches = searchMatches.filter(v => String(v.sku ?? '').trim() === row.sku);

if (matches.length === 0) {
  return [{ json: { ...row, status: 'missing', message: 'Exact SKU not found in Shopify', needsSync: false } }];
}
if (matches.length > 1) {
  return [{ json: { ...row, status: 'duplicate', message: 'More than one Shopify variant uses this exact SKU', needsSync: false } }];
}

const variant = matches[0];
const quantityEntry = variant.inventoryItem?.inventoryLevel?.quantities?.find(q => q.name === 'available');
const currentStock = quantityEntry?.quantity ?? null;
const currentPrice = Number(variant.price);

if (cfg.updateStock && currentStock === null) {
  const locationName = $('Validate Shopify Location').first().json.locationName;
  return [{ json: { ...row, status: 'error', message: `Variant has no inventory level at primary Shopify location${locationName ? ` "${locationName}"` : ''}`, needsSync: false, variantId: variant.id } }];
}

const targetStock = cfg.updateStock ? Math.max(row.supplierStock - Number(cfg.stockBuffer ?? 0), 0) : (currentStock ?? 0);
const targetPrice = cfg.updatePrice ? Math.round((row.supplierPrice * Number(cfg.priceMultiplier ?? 1) + Number.EPSILON) * 100) / 100 : currentPrice;

const stockChanged = Boolean(cfg.updateStock) && currentStock !== targetStock;
const priceChanged = Boolean(cfg.updatePrice) && Math.abs(currentPrice - targetPrice) > 0.000001;

return [{
  json: {
    ...row,
    productId: variant.product.id,
    variantId: variant.id,
    inventoryItemId: variant.inventoryItem.id,
    currentStock,
    currentPrice,
    targetStock,
    targetPrice,
    stockChanged,
    priceChanged,
    needsSync: stockChanged || priceChanged,
    status: stockChanged || priceChanged ? 'ready' : 'unchanged',
    message: stockChanged || priceChanged ? '' : 'No Shopify changes required',
    idempotencyKey: `n8n-supplier-sync:${cfg.syncRunId}:${row.sku}`.slice(0, 250)
  }
}];

parameters.jsonBody:
={{ {
  query: `mutation SyncVariant($productId: ID!, $variantId: ID!, $price: Money!, $inventoryInput: InventorySetQuantitiesInput!, $idempotencyKey: String!, $updatePrice: Boolean!, $updateInventory: Boolean!) {
    priceUpdate: productVariantsBulkUpdate(productId: $productId, variants: [{ id: $variantId, price: $price }]) @include(if: $updatePrice) { userErrors { field message } }
    inventoryUpdate: inventorySetQuantities(input: $inventoryInput) @include(if: $updateInventory) @idempotent(key: $idempotencyKey) { userErrors { code field message } }
  }`,
  variables: {
    productId: $json.productId,
    variantId: $json.variantId,
    price: String($json.targetPrice),
    inventoryInput: {
      name: 'available',
      reason: 'correction',
      referenceDocumentUri: `n8n://supplier-sync/${$('CONFIG - EDIT ME').first().json.syncRunId}/${$json.sku}`,
      quantities: [{
        inventoryItemId: $json.inventoryItemId,
        locationId: $('Validate Shopify Location').first().json.locationId,
        quantity: $json.targetStock,
        changeFromQuantity: $json.currentStock
      }]
    },
    idempotencyKey: $json.idempotencyKey,
    updatePrice: $json.priceChanged,
    updateInventory: $json.stockChanged
  }
} }}

