const prepared = $('Prepare Sync').item.json;
const response = $json;
const errors = [];

if (Array.isArray(response.errors)) errors.push(...response.errors.map(e => e.message));

for (const key of ['priceUpdate', 'inventoryUpdate']) {
  const userErrors = response.data?.[key]?.userErrors ?? [];
  errors.push(...userErrors.map(e => e.code ? `${e.code}: ${e.message}` : e.message));
}

if (errors.length) {
  return [{ json: { ...prepared, status: 'error', message: errors.join('; '), needsSync: false } }];
}

const changes = [];
if (prepared.stockChanged) changes.push(`stock ${prepared.currentStock} → ${prepared.targetStock}`);
if (prepared.priceChanged) changes.push(`price ${prepared.currentPrice} → ${prepared.targetPrice}`);

return [{ json: { ...prepared, status: 'updated', message: changes.join(', '), needsSync: false } }];

const items = $input.all().map(item => item.json);
const counts = { updated: 0, unchanged: 0, invalid: 0, missing: 0, duplicate: 0, error: 0 };

for (const item of items) {
  if (Object.prototype.hasOwnProperty.call(counts, item.status)) counts[item.status]++;
}

const location = $('Validate Shopify Location').first().json;
return [{ json: {
  totalRows: items.length,
  ...counts,
  shopifyLocationId: location.locationId,
  shopifyLocationName: location.locationName,
  completedAt: new Date().toISOString(),
  results: items
} }];
